// Auto-generated by r2factor. Manual edits will be overwritten on next split.

use super::misc::sorted2;
use super::segments::segments_properly_cross_3d;
use crate::mesh::types::Point;
use std::collections::HashSet;

pub(super) fn constraint_edges_from_facets(facets: &[[usize; 3]]) -> Vec<[usize; 2]> {
    let mut edges = HashSet::new();
    for &[a, b, c] in facets {
        edges.insert(sorted2([a, b]));
        edges.insert(sorted2([b, c]));
        edges.insert(sorted2([c, a]));
    }
    let mut edges: Vec<_> = edges.into_iter().collect();
    edges.sort_unstable();
    edges
}

/// Split positions along a missing constraint `edge`: the exact crossing
/// point of every Delaunay edge that properly crosses the segment (the
/// coplanar annulus / junction case), or the midpoint when no coplanar
/// blocker exists (generic skew blockage). Targeted crossings terminate the
/// Steiner cascade that blind midpoint splitting provokes between constraint
/// edges meeting at acute angles.
pub(super) fn constraint_edge_split_points(
    points: &[Point],
    tet_edges: &HashSet<[usize; 2]>,
    edge: [usize; 2],
) -> Vec<Point> {
    let p0 = points[edge[0]];
    let p1 = points[edge[1]];
    let mut params: Vec<f64> = Vec::new();
    for &other in tet_edges {
        if edge.iter().any(|v| other.contains(v)) {
            continue;
        }
        if let Some(hit) = segments_properly_cross_3d(p0, p1, points[other[0]], points[other[1]]) {
            let span = (p1.x - p0.x).abs() + (p1.y - p0.y).abs() + (p1.z - p0.z).abs();
            if span == 0.0 {
                continue;
            }
            let t = ((hit.x - p0.x).abs() + (hit.y - p0.y).abs() + (hit.z - p0.z).abs()) / span;
            if t > 1e-9 && t < 1.0 - 1e-9 {
                params.push(t);
            }
        }
    }
    params.sort_by(|x, y| x.partial_cmp(y).unwrap_or(std::cmp::Ordering::Equal));
    params.dedup_by(|a, b| (*a - *b).abs() < 1e-9);

    if params.is_empty() {
        params.push(0.5);
    }
    params
        .into_iter()
        .map(|t| {
            Point::new_3d(
                p0.x + (p1.x - p0.x) * t,
                p0.y + (p1.y - p0.y) * t,
                p0.z + (p1.z - p0.z) * t,
            )
        })
        .collect()
}
